using System;using System.Collections.Generic;using System.IO;using WordPadClone.Formats;class P{static void Main(){var files=new List<string>();files.AddRange(Directory.GetFiles("test-assets/corpus","*.docx"));files.AddRange(Directory.GetFiles("test-assets/odt","*.odt"));files.AddRange(Directory.GetFiles("test-assets/odt/extra","*.odt"));files.AddRange(new string[]{"test-assets/root/formato-carta-de-recomendacion.docx","test-assets/root/guia-presentacion-tesis-trabajos-grado.docx","test-assets/root/sample-long.docx","test-assets/sample.doc","test-assets/ascii.doc","test-assets/root/SampleDOCFile_100kb.doc"});Directory.CreateDirectory("tmp-regression/out");int ok=0,fail=0;foreach(var f in files){if(!File.Exists(f))continue;try{var fmt=DocumentFormats.Detect(f);var d=DocumentFormats.ReadModel(f,fmt);string ext=fmt==DocumentFormat.Doc?"docx":fmt.ToString().ToLowerInvariant();string o=Path.Combine("tmp-regression/out",Path.GetFileNameWithoutExtension(f)+"."+ext);if(File.Exists(o))File.Delete(o);if(File.Exists(o+".bak"))File.Delete(o+".bak");if(fmt==DocumentFormat.Odt)DocumentFormats.SaveOdt(o,d);else if(fmt==DocumentFormat.Rtf)DocumentFormats.SaveRtf(o,RtfWriter.Write(d,true));else DocumentFormats.SaveDocx(o,d);DocumentFormats.ReadModel(o,DocumentFormats.Detect(o));ok++;}catch(Exception ex){Console.WriteLine(Path.GetFileName(f)+" FAIL "+ex.Message);fail++;}}Console.WriteLine("CORPUS="+(ok+fail)+" OK="+ok+" FAIL="+fail);Environment.Exit(fail==0?0:1);}}
